:root {
  /* Brand Colors - No Purple, Violet, Magenta, Pink, or Lavender */
  --color-primary: #0052cc; /* Deep Tech Blue */
  --color-primary-dark: #003399;
 19  --color-secondary: #00d4ff; /* Bright Cyan Accent */
  --color-tertiary: #00ff88; /* Electric Green */

  /* Neutral Colors */
  --color-bg-main: #ffffff;
  --color-bg-contrast: #f5f7fa; /* Light Gray Background */
  --color-bg-dark: #0a192f; /* Deep Navy for Dark Mode Areas */
  --color-text-main: #102a43;
  --color-text-light: #506680;
  --color-text-white: #ffffff;
  --color-border: #d9e2ec;
}

/* Hero Section Styles */
.hero {
  background-color: var(--color-bg-dark);
  color: var(--color-text-white);
  padding: 120px 20px;
  text-align: center;
  position: relative;
  overflow: hidden;
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--color-primary);
  opacity: 0.1;
  pointer-events: none;
}

.hero-content {
  max-width: 800px;
  z-index: 2;
  position: relative;
}

.hero h1 {
  font-size: 3.5rem;
  font-weight: 800;
  margin-bottom: 1.5rem;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.hero h1 span {
  color: var(--color-secondary);
}

.hero p {
  font-size: 1.25rem;
  line-height: 1.6;
  margin-bottom: 2.5rem;
  opacity: 0.9;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* CTA Buttons */
.cta-group {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  padding: 14px 32px;
  border-radius: 6px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s ease;
  font-size: 1rem;
  border: 2px solid transparent;
  cursor: pointer;
  display: inline-block;
}

.btn-primary {
  background-color: var(--color-tertiary);
  color: var(--color-bg-dark);
}

.btn-primary:hover {
  background-color: #00cc6e;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(0, 255, 136, 0.25);
}

.btn-secondary {
  background-color: transparent;
  border-color: var(--color-secondary);
  color: var(--color-secondary);
}

.btn-secondary:hover {
  background-color: var(--color-secondary);
  color: var(--color-bg-dark);
}

/* Decorative shapes (flat colors) */
.hero-shape {
  position: absolute;
  border-radius: 50%;
  opacity: 0.15;
  z-index: 1;
}

.shape-1 {
  width: 300px;
  height: 300px;
  background-color: var(--color-tertiary);
  top: -50px;
  right: -50px;
}

.shape-2 {
  width: 200px;
  height: 200px;
  background-color: var(--color-primary);
  bottom: -40px;
  left: -40px;
}

:root {
  /* Color Palette - No purple, violet, magenta, pink, or lavender */
  --color-primary: #0066cc;
  --color-primary-dark: #004c99;
  --color-primary-light: #3388dd;
  --color-secondary: #00a86b;
  --color-secondary-dark: #007a4f;
  --color-accent: #ff6b35;
  --color-accent-dark: #cc5529;
  --color-background: #f8f9fa;
  --color-surface: #ffffff;
  --color-text-primary: #1a1a1a;
  --color-text-secondary: #5a5a5a;
  --color-text-light: #8a8a8a;
  --color-border: #e0e0e0;
  --color-success: #28a745;
  --color-warning: #ffc107;
  --color-error: #dc3545;
  --color-info: #17a2b8;
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
  background-color: var(--color-background);
  color: var(--color-text-primary);
  line-height: 1.6;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--color-primary);
  color: var(--color-surface);
  padding: 120px 20px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--color-primary-dark);
  opacity: 0.3;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  margin: 0 auto;
}

.hero-title {
  font-size: 3.5rem;
  font-weight: 700;
  margin-bottom: 20px;
  line-height: 1.2;
  color: var(--color-surface);
}

.hero-subtitle {
  font-size: 1.25rem;
  font-weight: 400;
  margin-bottom: 40px;
  color: var(--color-surface);
  opacity: 0.9;
}

.hero-cta {
  display: inline-block;
  background-color: var(--color-secondary);
  color: var(--color-surface);
  padding: 15px 35px;
  text-decoration: none;
  border-radius: 5px;
  font-weight: 600;
  font-size: 1rem;
  transition: background-color 0.3s ease;
}

.hero-cta:hover {
  background-color: var(--color-secondary-dark);
}

.hero-cta-secondary {
  background-color: transparent;
  border: 2px solid var(--color-surface);
  margin-left: 15px;
}

.hero-cta-secondary:hover {
  background-color: var(--color-surface);
  color: var(--color-primary);
}

