  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--color-background-light);
  opacity: 0.5;
  z-index: 0;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 1000px;
  padding: 0 2rem;
  text-align: left;
}

.hero-title {
  color: var(--color-white);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 700;
  margin-bottom: 1.5rem;
  line-height: 1.1;
}

.hero-subtitle {
  color: var(--color-accent);
