  --color-surface: #f5f7fa;
  --color-text-primary: #1a1a1a;
  --color-text-secondary: #5f6368;
  --color-text-light: #ffffff;
  --color-border: #e0e0e0;
  --color-success: #28a745;
  --color-warning: #ffc107;
  --color-error: #dc3545;
  --color-info: #17a2b8;
}

/* Hero Section Styles */
.hero {
  background-color: var(--color-background);
  padding: 120px 20px;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.hero-container {
  max-width: 1200px;
  margin: 0 auto;
  text-align: center;
  padding: 40px 20px;
}

.hero-title {
  font-size: 3.5rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 20px;
  line-height: 1.2;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--color-text-secondary);
  margin-bottom: 40px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.6;
}

.hero-cta {
  display: inline-block;
  background-color: var(--color-primary);
  color: var(--color-text-light);
  padding: 16px 32px;
  font-size: 1rem;
  font-weight: 600;
  text-decoration: none;
  border-radius: 4px;
  transition: background-color 0.2s ease;
  margin: 10px;
}

.hero-cta:hover {
  background-color: var(--color-primary-dark);
}

.hero-cta-secondary {
  background-color: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.hero-cta-secondary:hover {
  background-color: var(--color-primary);
  color: var(--color-text-light);
}

/* Hero Background Elements */
.hero-bg-shape {
  position: absolute;
  border-radius: 50%;
  opacity: 0.1;
  pointer-events: none;
}

.hero-bg-shape-1 {
  width: 400px;
  height: 400px;
  background-color: var(--color-primary);
  top: 10%;
  left: -100px;
}

.hero-bg-shape-2 {
  width: 300px;
  height: 300px;
  background-color: var(--color-secondary);
  bottom: 10%;
  right: -50px;
}

/* Additional Hero Variants */
.hero-dark {
  background-color: var(--color-text-primary);
}

.hero-dark .hero-title {
  color: var(--color-text-light);
}

.hero-dark .hero-subtitle {
  color: var(--color-text-secondary);
}

.hero-dark .hero-cta {
  background-color: var(--color-primary);
}

.hero-dark .hero-cta-secondary {
  color: var(--color-text-light);
  border-color: var(--color-text-light);
}

.hero-dark .hero-cta-secondary:hover {
  background-color: var(--color-text-light);
  color: var(--color-text-primary);
}

/* Responsive Adjustments */
@media (max-width: 768px) {
  .hero {
    padding: 80px 15px;
    min-height: 60vh;
  }

  .hero-title {
    font-size: 2.5rem;
  }

  .hero-subtitle {
    font-size: 1.1rem;
  }

  .hero-bg-shape-1,
  .hero-bg-shape-2 {
    display: none;
  }
}

