  --radius-full: 9999px;

  /* Z-Index */
  --z-index-base: 0;
  --z-index-dropdown: 1000;
  --z-index-sticky: 1024;
  --z-index-fixed: 1048;
  --z-index-modal: 1080;
  --z-index-tooltip: 1100;
}

