  opacity: 0.95;
  z-index: -1;
}

/* Hero Content Container */
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 1200px;
  padding: 2rem;
  text-align: center;
}

/* Hero Headline */
.hero-headline {
  font-size: 3.5rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--color-text-light);
  line-height: 1.2;
}

/* Hero Subheadline */
.hero-subheadline {
  font-size: 1.5rem;
  font-weight: 400;
  margin-bottom: 2.5rem;
  color: var(--color-text-light);
  opacity: 0.9;
  max-width: 800px;
  margin-left: auto;
  margin-right: auto;
}

