.hero-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.btn-primary {
  background-color: var(--color-button-primary);
  color: var(--color-text-light);
  padding: 1rem 2rem;
  border: none;
  border-radius: 4px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.3s ease;
}

.btn-primary:hover {
  background-color: var(--color-button-primary-hover);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-text-light);
  padding: 1rem 2rem;
  border: 2px solid var(--color-text-light);
  border-radius: 4px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.btn-secondary:hover {
  background-color: var(--color-text-light);
  color: var(--color-bg-dark);
}

/* Hero Features List */
.hero-features {
  display: flex;
  gap: 3rem;
  justify-content: center;
  margin-top: 4rem;
  flex-wrap: wrap;
}

