:root {
  /* Primary Colors */
  --color-primary: #0a2540; /* Deep Navy */
  --color-primary-dark: #05172a; /* Darker Navy */
  --color-primary-light: #1a3b5d; /* Lighter Navy */

  /* Secondary Colors */
