:root {
  /* Brand Colors - Professional Healthcare Palette */
  --primary-blue: #0052cc;
  --primary-blue-hover: #003d99;

  --secondary-teal: #008b8b;
 11  --secondary-teal-light: #e0f2f1;

  --accent-green: #2e7d32;
  --accent-green-light: #e8f5e9;

  --neutral-gray-dark: #333333;
  --neutral-gray-medium: #666666;
  --neutral-gray-light: #f5f5f5;
  --neutral-white: #ffffff;

  /* Semantic Colors */
  --text-primary: var(--neutral-gray-dark);
  --text-secondary: var(--neutral-gray-medium);
 11  --bg-section: var(--neutral-white);

  /* Spacing & Layout */
  --section-padding: 4rem 2rem;
  --max-width-container: 1200px;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--neutral-white);
  color: var(--text-primary);
  padding: 6rem 2rem;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--secondary-teal-light);
  opacity: 0.15;
  z-index: 1;
}

.hero-container {
  max-width: var(--max-width-container);
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.hero-title {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--primary-blue);
  margin-bottom: 1.5rem;
  line-height: 1.2;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-secondary);
  margin-bottom: 2rem;
  line-height: 1.6;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
}

.hero-cta {
  display: inline-block;
  background-color: var(--primary-blue);
  color: var(--neutral-white);
  padding: 1rem 2.5rem;
  text-decoration: none;
  font-weight: 600;
  border-radius: 4px;
  border: 2px solid var(--primary-blue);
  transition: background-color 0.2s ease, color 0.2s ease;
}

.hero-cta:hover {
  background-color: var(--primary-blue-hover);
  border-color: var(--primary-blue-hover);
  color: var(--neutral-white);
}

.hero-cta:focus {
  outline: 3px solid var(--secondary-teal);
  outline-offset: 2px;
}

/* Additional Hero Elements */
.hero-features {
  margin-top: 3rem;
  display: flex;
  justify-content: center;
  gap: 2rem;
  flex-wrap: wrap;
}

.hero-feature-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--neutral-gray-dark);
  font-weight: 500;
  background-color: var(--neutral-white);
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  border: 1px solid var(--neutral-gray-light);
}

