/* CSS Variables */
:root {
  /* Primary Colors - Healthcare Professional Palette */
  --color-primary-blue: #0056b3;
  --color-primary-teal: #008080;
  --color-primary-green: #2e7d32;
  --color-primary-cyan: #00bcd4;

  /* Neutral Colors */
  --color-white: #ffffff;
  --color-off-white: #f8f9fa;
  --color-light-gray: #e9ecef;
  --color-medium-gray: #6c757d;
  --color-dark-gray: #343a40;
  --color-black: #212529;

  /* Semantic Colors */
  --color-success: #28a745;
  --color-warning: #ffc107;
  --color-danger: #dc3545;
  --color-info: #17a2b8;

  /* Background Colors */
  --bg-primary: var(--color-white);
  --bg-secondary: var(--color-off-white);
  --bg-accent: var(--color-primary-teal);

  /* Text Colors */
  --text-primary: var(--color-black);
  --text-secondary: var(--color-medium-gray);
  --text-light: var(--color-white);
  --text-muted: #6c757d;

  /* Border Colors */
  --border-color: var(--color-light-gray);

  /* Shadow Colors */
  --shadow-color: rgba(0, 0, 0, 0.1);
  --shadow-color-dark: rgba(0, 0, 0, 0.2);

  /* Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;
  --spacing-3xl: 4rem;

  /* Typography */
  --font-family-base: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  --font-family-heading: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 2rem;
  --font-size-4xl: 2.5rem;
  --font-size-5xl: 3rem;

  /* Border Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
  --transition-slow: 350ms ease;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--color-primary-teal);
  padding: var(--spacing-3xl) var(--spacing-xl);
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 128, 128, 0.1);
  pointer-events: none;
}

.hero-container {
  max-width: 1200px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
}

.hero-content {
  display: flex;
  flex-direction: column;
