  --color-bg-secondary: #f8f9fa;
  --color-bg-tertiary: #e9ecef;

  /* Text Colors */
  --color-text-primary: #212529;
  --color-text-secondary: #495057;
  --color-text-muted: #6c757d;
  --color-text-inverse: #ffffff;

  /* Border Colors */
  --color-border: #dee2e6;
  --color-border-dark: #adb5bd;

  /* Shadow Colors */
  --shadow-color: rgba(0, 0, 0, 0.1);
  --shadow-color-strong: rgba(0, 0, 0, 0.15);

  /* Hero Section Specific */
  --hero-bg-color: #f0f7ff;
  --hero-text-color: #212529;
  --hero-accent-color: #0066cc;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--hero-bg-color);
  color: var(--hero-text-color);
  padding: 80px 20px;
  min-height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--color-bg-primary);
  opacity: 0.95;
  z-index: 0;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 1200px;
  margin: 0 auto;
  text-align: center;
}

.hero-title {
  font-size: 3rem;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-bottom: 20px;
  line-height: 1.2;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--color-text-secondary);
  margin-bottom: 30px;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.6;
}

.hero-cta {
  display: inline-block;
  background-color: var(--color-primary);
  color: var(--color-text-inverse);
  padding: 15px 35px;
  text-decoration: none;
  font-weight: 600;
  font-size: 1rem;
  border-radius: 4px;
  transition: background-color 0.2s ease;
}

.hero-cta:hover {
  background-color: var(--color-primary-dark);
}

.hero-image-container {
  margin-top: 40px;
}

.hero-image {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
  background-color: var(--color-neutral-200);
}

/* Hero Section Variants */
.hero-section-alt {
  background-color: var(--color-bg-secondary);
}

.hero-section-dark {
  background-color: var(--color-neutral-800);
  color: var(--color-text-inverse);
}

.hero-section-dark .hero-title {
  color: var(--color-text-inverse);
}

