:root {
  /* Core Brand Colors */
  --color-primary: #0ea5e9; /* Sky Blue */
  --color-primary-dark: #0284c7;
  --color-secondary: #f59e0b; /* Amber */
  --color-secondary-dark: #d97706;

  /* Neutrals */
  --color-bg: #f8fafc; /* Slate 50 */
  --color-surface: #ffffff;
  --color-text-main: #0f172a; /* Slate 900 */
  --color-text-muted: #64748b; /* Slate 500 */
  --color-border: #e2e8f0; /* Slate 200 */

  /* Utility */
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --radius-md: 0.375rem;
  --radius-lg: 0.5rem;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--color-bg);
  padding: 4rem 1.5rem;
  position: relative;
  overflow: hidden;
}

.hero-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 2rem;
  position: relative;
  z-index: 10;
}

.hero-content {
  flex: 1;
  max-width: 600px;
}

.hero-image {
  flex: 1;
  display: none; /* Hidden on mobile by default */
  align-items: center;
  justify-content: center;
}

.hero-badge {
  display: inline-block;
  background-color: var(--color-surface);
  color: var(--color-primary-dark);
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
  border: 1px solid var(--color-border);
}

.hero-title {
  font-size: 2.5rem;
  line-height: 1.2;
  color: var(--color-text-main);
  margin-bottom: 1rem;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--color-text-muted);
  margin-bottom: 2rem;
  line-height: 1.6;
}

/* Decorative Background Element (Flat Color Only) */
.hero-decoration {
  position: absolute;
  top: -50px;
  right: -50px;
  width: 400px;
  height: 400px;
  background-color: #cffafe; /* Light Cyan */
  border-radius: 50%;
  opacity: 0.6;
  z-index: 1;
  pointer-events: none;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: background-color 0.2s ease, transform 0.1s ease;
  cursor: pointer;
  border: none;
  text-decoration: none;
  font-size: 1rem;
}

.btn-primary {
  background-color: var(--color-primary);
  color: white;
}

.btn-primary:hover {
  background-color: var(--color-primary-dark);
  transform: translateY(-1px);
}

.btn-secondary {
  background-color: var(--color-secondary);
  color: white;
  margin-left: 0.75rem;
}

.btn-secondary:hover {
  background-color: var(--color-secondary-dark);
  transform: translateY(-1px);
}

/* Desktop Media Query */
@media (min-width: 768px) {
  .hero-section {
    padding: 6rem 1.5rem;
  }

  .hero-image {
    display: flex;
  }

  .hero-title {
    font-size: 3.5rem;
  }

  .hero-decoration {
    width: 600px;
    height: 600px;
    top: -100px;
    right: -100px;
  }
}

