  /* Core Brand Colors */
  --color-primary: #1a1a2e;        /* Deep Navy */
  --color-secondary: #16213e;      /* Dark Blue */
  --color-accent: #e94560;         /* Coral Red */
  --color-accent-hover: #d63453;   /* Darker Coral */

  /* Neutral Palette */
  --color-background: #f8f9fa;     /* Off-White */
  --color-surface: #ffffff;        /* Pure White */
  --color-text-primary: #212529;   /* Near Black */
  --color-text-secondary: #6c757d; /* Medium Gray */
  --color-text-muted: #adb5bd;     /* Light Gray */
  --color-border: #dee2e6;         /* Light Border */

  /* Status Colors */
  --color-success: #28a745;        /* Green */
  --color-warning: #ffc107;        /* Amber */
  --color-error: #dc3545;          /* Red */
  --color-info: #17a2b8;           /* Teal */

  /* Typography */
  --font-family-primary: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-family-heading: 'Playfair Display', Georgia, serif;

  /* Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;
  --spacing-3xl: 4rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0 20px 25px rgba(0, 0, 0, 0.15);

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
  --transition-slow: 350ms ease;
}

/* Hero Section Styles */
.hero {
  position: relative;
  width: 100%;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--color-primary);
  color: var(--color-surface);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--color-secondary);
  opacity: 0.95;
}

.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  padding: var(--spacing-2xl) var(--spacing-lg);
}

.hero-badge {
  display: inline-block;
  background-color: var(--color-accent);
  color: var(--color-surface);
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-bottom: var(--spacing-lg);
}

.hero-title {
  font-family: var(--font-family-heading);
  font-size: clamp(2.5rem, 5vw, 4rem);
