:root {
  /* Primary Brand Colors */
  --color-primary: #1a1a2e;
  --color-primary-light: #2d2d4a;
  --color-primary-dark: #0f0f1a;

  /* Secondary Accent Colors (Warm/Earth Tones) */
  --color-secondary: #e67e22;
  --color-secondary-light: #f39c12;
  --color-secondary-dark: #d35400;

  /* Neutral Colors */
  --color-white: #ffffff;
  --color-off-white: #f8f9fa;
  --color-gray-100: #f1f3f5;
  --color-gray-200: #e9ecef;
  --color-gray-300: #dee2e6;
  --color-gray-400: #ced4da;
  --color-gray-500: #adb5bd;
  --color-gray-600: #6c757d;
  --color-gray-700: #495057;
  --color-gray-800: #343a40;
  --color-gray-900: #212529;
  --color-black: #000000;

  /* Success/Status Colors */
  --color-success: #27ae60;
  --color-success-light: #2ecc71;
  --color-error: #e74c3c;
  --color-error-light: #c0392b;
  --color-warning: #f1c40f;
  --color-warning-dark: #f39c12;

  /* Background Colors */
  --bg-primary: var(--color-white);
  --bg-secondary: var(--color-off-white);
  --bg-dark: var(--color-primary);
  --bg-accent: var(--color-secondary);
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--color-primary);
  color: var(--color-white);
  min-height: 70vh;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.hero-section::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--color-primary-dark);
  opacity: 0.5;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  text-align: center;
  max-width: 800px;
  padding: 2rem;
}

.hero-title {
  font-size: 3.5rem;
  font-weight: 700;
  color: var(--color-white);
  margin-bottom: 1rem;
  line-height: 1.2;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--color-gray-300);
  margin-bottom: 2rem;
  font-weight: 400;
}

.hero-cta {
  display: inline-block;
  background-color: var(--color-secondary);
  color: var(--color-white);
  padding: 1rem 2.5rem;
  font-size: 1.125rem;
  font-weight: 600;
  text-decoration: none;
  border-radius: 4px;
  transition: background-color 0.3s ease;
}

.hero-cta:hover {
  background-color: var(--color-secondary-dark);
}

.hero-background {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: var(--color-primary-light);
  opacity: 0.3;
  z-index: 0;
}
