  --neutral-600: #475569;  /* Slate Light */
  --neutral-100: #f1f5f9;  /* Light Gray */
  --neutral-50:  #f8fafc;  /* Very Light Gray */
  --white:       #ffffff;

  /* Semantic Colors */
  --success: #10b981;      /* Emerald */
  --warning: #f59e0b;      /* Amber */
  --error:   #ef4444;      /* Red */

  /* Typography */
  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;

  /* Spacing */
  --spacing-md: 1.5rem;
  --spacing-lg: 3rem;
  --spacing-xl: 5rem;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--neutral-900);
  color: var(--white);
  font-family: var(--font-sans);
  padding: var(--spacing-xl) var(--spacing-lg);
  position: relative;
  overflow: hidden;
  min-height: 600px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}

/* Decorative background shapes (flat colors only) */
.hero-section::before {
  content: "";
  position: absolute;
  top: -50px;
  right: -50px;
  width: 300px;
  height: 300px;
  background-color: var(--primary);
  opacity: 0.1;
  border-radius: 50%;
  z-index: 1;
}

.hero-section::after {
  content: "";
  position: absolute;
  bottom: -80px;
  left: -80px;
  width: 400px;
  height: 400px;
  background-color: var(--secondary);
  opacity: 0.08;
  border-radius: 50%;
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
}

.hero-title {
  font-size: 3.5rem;
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--spacing-md);
  color: var(--white);
  letter-spacing: -0.02em;
}

.hero-subtitle {
  font-size: 1.25rem;
  line-height: 1.6;
  margin-bottom: var(--spacing-lg);
  color: var(--neutral-100);
  font-weight: 400;
}

.hero-cta {
  display: inline-block;
  padding: 1rem 2.5rem;
  font-size: 1.125rem;
  font-weight: 600;
  text-decoration: none;
  border-radius: 8px;
  transition: all 0.2s ease;
  border: 2px solid var(--primary);
  background-color: var(--primary);
  color: var(--white);
  cursor: pointer;
}

.hero-cta:hover {
  background-color: transparent;
  color: var(--primary);
  transform: translateY(-2px);
}

.hero-cta.secondary {
  background-color: transparent;
  border-color: var(--secondary);
  color: var(--secondary);
  margin-left: 1rem;
}

.hero-cta.secondary:hover {
  background-color: var(--secondary);
  color: var(--white);
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .hero-section {
    padding: var(--spacing-lg) var(--spacing-md);
    min-height: 500px;
  }

  .hero-title {
    font-size: 2.5rem;
  }

  .hero-subtitle {
    font-size: 1.1rem;
  }

  .hero-cta {
    display: block;
    width: 100%;
    max-width: 300px;
