:root {
    /* Brand Colors */
    --color-primary: #0052cc; /* Strong Blue */
    --color-primary-hover: #003d99;
    --color-secondary: #00b894; /* Vibrant Teal */
    --color-secondary-hover: #008f73;
    --color-accent: #ff9f43; /* Warm Orange */

    /* Neutral Colors */
    --color-text-main: #1a1a1a;
    --color-text-muted: #5e6c77;
    --color-text-light: #ffffff;
    --color-background: #f4f6f8;
    --color-surface: #ffffff;
    --color-border: #dfe1e6;

    /* Semantic Colors */
    --color-success: #2ecc71;
    --color-error: #e74c3c;
    --color-warning: #f1c40f;

    /* Spacing & Layout */
    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2.5rem;
    --spacing-xl: 4rem;

    /* Typography */
    --font-family-main: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --font-weight-regular: 400;
    --font-weight-bold: 700;
    --font-weight-black: 900;
}

/* Hero Section Styles */
.hero-section {
    background-color: var(--color-primary);
    color: var(--color-text-light);
    padding: var(--spacing-xl) var(--spacing-md);
    position: relative;
    overflow: hidden;
    text-align: center;
}

/* Decorative shapes for visual interest without gradients */
.hero-section::before {
    content: "";
    position: absolute;
    top: -50px;
    right: -50px;
    width: 200px;
    height: 200px;
    background-color: rgba(255, 255, 255, 0.1);
    border-radius: 50%;
    z-index: 1;
}

.hero-section::after {
    content: "";
    position: absolute;
    bottom: -80px;
    left: -80px;
    width: 300px;
    height: 300px;
    background-color: rgba(0, 184, 148, 0.2); /* Secondary color overlay */
    border-radius: 50%;
    z-index: 1;
}

.hero-content {
    position: relative;
    z-index: 2;
    max-width: 800px;
    margin: 0 auto;
}

.hero-title {
    font-family: var(--font-family-main);
    font-size: 2.5rem;
    font-weight: var(--font-weight-black);
    line-height: 1.2;
    margin-bottom: var(--spacing-sm);
    color: var(--color-text-light);
}

.hero-subtitle {
    font-family: var(--font-family-main);
    font-size: 1.125rem;
    font-weight: var(--font-weight-regular);
    line-height: 1.6;
    margin-bottom: var(--spacing-lg);
    opacity: 0.9;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.hero-cta-container {
    display: flex;
    justify-content: center;
    gap: var(--spacing-sm);
    flex-wrap: wrap;
}

/* Button Styles */
.btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    font-family: var(--font-family-main);
    font-weight: var(--font-weight-bold);
    text-decoration: none;
    border-radius: 6px;
    transition: background-color 0.2s ease, transform 0.1s ease;
    cursor: pointer;
    border: none;
}

.btn:active {
    transform: translateY(1px);
}

.btn-primary {
    background-color: var(--color-accent);
    color: var(--color-text-main);
}

.btn-primary:hover {
    background-color: #e68a30; /* Slightly darker orange */
}

.btn-secondary {
    background-color: transparent;
    color: var(--color-text-light);
    border: 2px solid var(--color-text-light);
}

.btn-secondary:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

