:root {
  /* Primary Colors */
  --color-primary: #1a1a2e;
  --color-primary-light: #2d2d44;
  --color-primary-dark: #0f0f1a;

  /* Accent Colors */
  --color-accent: #f4a261;
  --color-accent-light: #f7b882;
  --color-accent-dark: #d4884a;

  /* Neutral Colors */
  --color-white: #ffffff;
  --color-off-white: #f8f9fa;
  --color-gray-100: #e9ecef;
  --color-gray-200: #dee2e6;
  --color-gray-300: #ced4da;
  --color-gray-400: #adb5bd;
  --color-gray-500: #6c757d;
  --color-gray-600: #495057;
  --color-gray-700: #343a40;
  --color-gray-800: #212529;
  --color-gray-900: #121212;

  /* Semantic Colors */
  --color-success: #28a745;
  --color-success-light: #3dcb66;
  --color-warning: #ffc107;
  --color-warning-dark: #e0a800;
  --color-error: #dc3545;
  --color-error-light: #e4606d;
  --color-info: #17a2b8;
  --color-info-light: #20c9da;

  /* Background Colors */
  --bg-primary: var(--color-white);
  --bg-secondary: var(--color-off-white);
  --bg-dark: var(--color-primary);
  --bg-accent: var(--color-accent);

  /* Text Colors */
  --text-primary: var(--color-gray-900);
  --text-secondary: var(--color-gray-600);
  --text-muted: var(--color-gray-500);
  --text-light: var(--color-white);
  --text-accent: var(--color-accent-dark);

  /* Border Colors */
  --border-color: var(--color-gray-200);
  --border-color-dark: var(--color-gray-400);

  /* Shadow */
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0 20px 25px rgba(0, 0, 0, 0.15);

  /* Spacing */
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-2xl: 3rem;
  --spacing-3xl: 4rem;

  /* Typography */
  --font-family-base: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.25rem;
  --font-size-2xl: 1.5rem;
  --font-size-3xl: 1.875rem;
  --font-size-4xl: 2.25rem;
  --font-size-5xl: 3rem;

  /* Border Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--color-primary);
  color: var(--text-light);
  position: relative;
  overflow: hidden;
}

