:root {
  /* Primary Colors */
  --color-primary-teal: #008080;
  --color-primary-teal-dark: #006666;
  --color-primary-teal-light: #40a3a3;

  /* Secondary Colors */
  --color-secondary-cyan: #00acc1;
  --color-secondary-cyan-dark: #00838f;

  /* Neutral Colors */
  --color-neutral-white: #ffffff;
  --color-neutral-light-gray: #f5f7fa;
  --color-neutral-medium-gray: #b0bec5;
  --color-neutral-dark-gray: #37474f;
  --color-neutral-black: #263238;

  /* Semantic Colors */
  --color-success-green: #2e7d32;
  --color-success-green-light: #a5d6a7;
  --color-warning-orange: #ef6c00;
  --color-warning-orange-light: #ffcc80;
  --color-info-blue: #1565c0;
  --color-info-blue-light: #90caf9;

  /* Text Colors */
  --color-text-primary: #263238;
  --color-text-secondary: #546e7a;
  --color-text-light: #78909c;
  --color-text-on-dark: #ffffff;

  /* Background Colors */
  --color-bg-light: #f5f7fa;
  --color-bg-white: #ffffff;
  --color-bg-dark: #263238;

  /* Border Colors */
  --color-border-light: #cfd8dc;
  --color-border-medium: #90a4ae;
}

/* Hero Section Styles */
.hero-section {
  background-color: var(--color-primary-teal);
  color: var(--color-text-on-dark);
  padding: 80px 20px;
  min-height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero-section::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 128, 128, 0.1);
  pointer-events: none;
}

.hero-content {
  max-width: 800px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
}

.hero-title {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 20px;
  color: var(--color-text-on-dark);
  line-height: 1.2;
}

.hero-subtitle {
  font-size: 1.25rem;
  font-weight: 400;
  margin-bottom: 30px;
  color: var(--color-text-on-dark);
  opacity: 0.9;
  line-height: 1.6;
}

.hero-cta {
  display: inline-block;
  background-color: var(--color-neutral-white);
  color: var(--color-primary-teal-dark);
  padding: 15px 30px;
  text-decoration: none;
  font-weight: 600;
  border-radius: 4px;
  transition: background-color 0.3s ease;
}

.hero-cta:hover {
  background-color: var(--color-neutral-light-gray);
}

/* Hero Background Variations */
.hero-section-alt {
  background-color: var(--color-secondary-cyan);
}

.hero-section-dark {
  background-color: var(--color-bg-dark);
}

/* Responsive Adjustments */
@media (max-width: 768px) {
  .hero-section {
    padding: 60px 15px;
    min-height: 400px;
  }

  .hero-title {
    font-size: 1.875rem;
  }

  .hero-subtitle {
    font-size: 1rem;
  }
}
